<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import ProductPicker from './ProductPicker.vue'
import UnitPicker from './UnitPicker.vue'
import { apiError, can, dateTime, jsonBody, localDateTimeInput, money, opsRequest, pageParams, type Row } from './shared'

const props=defineProps<{token:string;permissions:string[];initialProductId?:string}>()
const writable=computed(()=>can(props.permissions,'inventory:write'))
const tab=ref('stock'),q=ref(''),page=ref(1),size=ref(10),total=ref(0),loading=ref(false),error=ref('')
const stocks=ref<Row[]>([]),units=ref<Row[]>([]),movements=ref<Row[]>([]),warehouses=ref<Row[]>([]),trace=ref<Row[]>([]),movementDetail=ref<Row|null>(null)
const showReceipt=ref(false),showIssue=ref(false),showAssembly=ref(false),showDisassembly=ref(false),showInspection=ref(false),showBundleComponents=ref(false)
const movementDialogOpen=computed({get:()=>!!movementDetail.value,set:(open:boolean)=>{if(!open)movementDetail.value=null}})
const receipt=reactive<any>({type:'purchase',warehouse_id:'',occurred_at:localDateTimeInput(),recipient:'',notes:'',items:[] as Row[]})
const issue=reactive<any>({type:'sale',warehouse_id:'',occurred_at:localDateTimeInput(),recipient:'',reason:'',expected_return_at:'',sales_order_id:'',carrier:'',tracking_number:'',shipping_cost:'0',notes:'',unit_ids:[] as string[]})
const assembly=reactive<any>({product_id:'',product_label:'',bom_configured:null,serial_number:'',batch_number:'',warehouse_id:'',occurred_at:localDateTimeInput(),unit_ids:[] as string[],notes:''})
const disassembly=reactive<any>({unit_ids:[] as string[],occurred_at:localDateTimeInput(),reason:''})
const inspection=reactive<any>({unit_id:'',warehouse_id:'',occurred_at:localDateTimeInput(),result:'available',reason:''})
const bundleComponents=reactive<any>({unit_id:'',warehouse_id:'',occurred_at:localDateTimeInput(),reason:'补录套装组成',unit_ids:[] as string[]})
const orderQuery=ref(''),orderPage=ref(1),orderRows=ref<Row[]>([]),orderTotal=ref(0),orderLoading=ref(false),selectedOrder=ref<Row|null>(null)
let timer:ReturnType<typeof setTimeout>|undefined,orderTimer:ReturnType<typeof setTimeout>|undefined
const types:Record<string,string>={purchase:'采购入库',initial:'期初入库',return:'退货入库',borrow_return:'借样归还',sale:'销售出库',sample:'寄样',borrow:'借样',internal:'内部领用',scrap:'报废',assembly:'组装套装',disassembly:'拆解套装',inspection:'质检处理'}
const status:Record<string,string>={available:'可用',reserved:'已预留',pending:'待检',borrowed:'借出',shipped:'已出库',assembled:'已组套',disassembled:'已拆套',scrapped:'已报废'}
async function load(){loading.value=true;error.value='';try{
  const params=pageParams(page.value,size.value,q.value)
  if(tab.value==='stock'){const result=await opsRequest<{items:Row[];total:number}>(props.token,`/stock?${params}`);stocks.value=result.items;total.value=result.total}
  else if(tab.value==='units'){const result=await opsRequest<{items:Row[];total:number}>(props.token,`/units?${params}`);units.value=result.items;total.value=result.total}
  else if(tab.value==='movements'){const result=await opsRequest<{items:Row[];total:number}>(props.token,`/movements?${params}`);movements.value=result.items;total.value=result.total}
}catch(e){error.value=apiError(e)}finally{loading.value=false}}
async function loadWarehouses(){try{warehouses.value=await opsRequest<Row[]>(props.token,'/warehouses')}catch(e){error.value=apiError(e)}}
watch(q,()=>{clearTimeout(timer);page.value=1;timer=setTimeout(()=>void load(),300)})
watch(page,()=>void load())
watch([size,tab],()=>{page.value=1;void load()})
onMounted(async()=>{await Promise.all([loadWarehouses(),load()]);if(props.initialProductId){try{const result=await opsRequest<{items:Row[];hasMore:boolean}>(props.token,`/catalog?id=${encodeURIComponent(props.initialProductId)}`);tab.value='stock';q.value=result.items[0]?.sku||''}catch(e){error.value=apiError(e)}}})
async function openReceipt(productId=''){Object.assign(receipt,{type:'purchase',warehouse_id:warehouses.value[0]?.id||'',occurred_at:localDateTimeInput(),recipient:'',notes:'',items:[]});if(productId){try{const result=await opsRequest<{items:Row[];hasMore:boolean}>(props.token,`/catalog?id=${encodeURIComponent(productId)}`);if(result.items[0])addReceiptItem(result.items[0])}catch(e){error.value=apiError(e)}}showReceipt.value=true}
function addReceiptItem(product?:Row|null){receipt.items.push({product_id:product?.id||'',product_label:product?`${product.sku} · ${product.name}`:'',product_kind:product?.kind||'',traceability_pending:product?.kind==='bundle',batch_number:'',serial_text:''})}
function removeReceiptItem(index:number){receipt.items.splice(index,1)}
async function submitReceipt(){if(!receipt.warehouse_id||!receipt.items.length||receipt.items.some((i:Row)=>!i.product_id||!i.batch_number.trim()||!String(i.serial_text||'').split(/\r?\n/).some((serial:string)=>serial.trim()))){error.value='请选择仓库，并为每个入库商品填写型号、生产批号和厂家序列号';return}
  const payload={type:receipt.type,warehouse_id:receipt.warehouse_id,occurred_at:new Date(receipt.occurred_at).toISOString(),recipient:receipt.recipient,notes:receipt.notes,items:receipt.items.map((i:Row)=>({product_id:i.product_id,batch_number:i.batch_number.trim(),serial_numbers:String(i.serial_text||'').split(/\r?\n/).map((s:string)=>s.trim()).filter(Boolean),...(i.product_kind==='bundle'?{traceability_pending:true}:{})}))}
  loading.value=true;error.value='';try{await opsRequest(props.token,'/receipts',{method:'POST',body:jsonBody(payload)});showReceipt.value=false;ElMessage.success('入库已确认并记录');tab.value='movements';await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function openIssue(){Object.assign(issue,{type:'sale',warehouse_id:warehouses.value[0]?.id||'',occurred_at:localDateTimeInput(),recipient:'',reason:'',expected_return_at:'',sales_order_id:'',carrier:'',tracking_number:'',shipping_cost:'0',notes:'',unit_ids:[]});selectedOrder.value=null;orderQuery.value='';orderPage.value=1;void loadOrders();showIssue.value=true}
async function loadOrders(){orderLoading.value=true;try{const params=pageParams(orderPage.value,10,orderQuery.value);const result=await opsRequest<{items:Row[];total:number}>(props.token,`/orders?${params}`);orderRows.value=result.items;orderTotal.value=result.total}catch(e){error.value=apiError(e)}finally{orderLoading.value=false}}
watch(orderQuery,()=>{clearTimeout(orderTimer);orderPage.value=1;orderTimer=setTimeout(()=>void loadOrders(),280)})
watch(orderPage,()=>void loadOrders())
watch(()=>issue.type,()=>{issue.unit_ids=[];if(issue.type!=='sale'){issue.sales_order_id='';selectedOrder.value=null}})
watch(()=>issue.warehouse_id,()=>{issue.unit_ids=[]})
function selectIssueOrder(order:Row){if(issue.sales_order_id!==order.id)issue.unit_ids=[];selectedOrder.value=order;issue.sales_order_id=order.id}
async function submitIssue(){if(!issue.warehouse_id||!issue.unit_ids.length||!issue.reason.trim()||!issue.recipient.trim()){error.value='请填写仓库、接收方、用途或原因，并选择至少一件实物';return}if(issue.type==='sale'&&!issue.sales_order_id){error.value='销售出库必须关联销售订单';return}
  if(issue.type==='borrow'&&!issue.expected_return_at){error.value='借样出库必须填写预计归还时间';return}
  const payload={type:issue.type,warehouse_id:issue.warehouse_id,occurred_at:new Date(issue.occurred_at).toISOString(),recipient:issue.recipient,reason:issue.reason,...(issue.type==='borrow'&&issue.expected_return_at?{expected_return_at:new Date(issue.expected_return_at).toISOString()}:{}),...(issue.type==='sale'?{sales_order_id:issue.sales_order_id}:{}),carrier:issue.carrier,tracking_number:issue.tracking_number,shipping_cost:String(issue.shipping_cost||0),notes:issue.notes,unit_ids:issue.unit_ids}
  loading.value=true;error.value='';try{await opsRequest(props.token,'/issues',{method:'POST',body:jsonBody(payload)});showIssue.value=false;ElMessage.success('出库已确认并记录');tab.value='movements';await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function openAssembly(){Object.assign(assembly,{product_id:'',product_label:'',bom_configured:null,serial_number:'',batch_number:'',warehouse_id:warehouses.value[0]?.id||'',occurred_at:localDateTimeInput(),unit_ids:[],notes:''});showAssembly.value=true}
async function submitAssembly(){if(!assembly.product_id||!assembly.serial_number.trim()||!assembly.batch_number.trim()||!assembly.warehouse_id||!assembly.unit_ids.length){error.value='请填写套装商品、追溯码、生产批号、仓库并选择组成件';return}const payload={product_id:assembly.product_id,serial_number:assembly.serial_number.trim(),batch_number:assembly.batch_number.trim(),warehouse_id:assembly.warehouse_id,occurred_at:new Date(assembly.occurred_at).toISOString(),unit_ids:assembly.unit_ids,notes:assembly.notes};loading.value=true;try{await opsRequest(props.token,'/assemblies',{method:'POST',body:jsonBody(payload)});showAssembly.value=false;ElMessage.success('套装已组装并记录');tab.value='movements';await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function openDisassembly(){Object.assign(disassembly,{unit_ids:[],warehouse_id:warehouses.value[0]?.id||'',occurred_at:localDateTimeInput(),reason:''});showDisassembly.value=true}
function updateDisassemblyUnits(rows:Row[]){disassembly.warehouse_id=rows[0]?.warehouse_id||''}
async function submitDisassembly(){if(!disassembly.unit_ids.length||!disassembly.warehouse_id||!disassembly.reason.trim()){error.value='请选择一套实物和仓库，并填写拆套原因';return}loading.value=true;try{await opsRequest(props.token,'/disassemblies',{method:'POST',body:jsonBody({unit_id:disassembly.unit_ids[0],warehouse_id:disassembly.warehouse_id,occurred_at:new Date(disassembly.occurred_at).toISOString(),reason:disassembly.reason})});showDisassembly.value=false;ElMessage.success('拆套已完成并记录');tab.value='movements';await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function beginInspection(unit:Row){Object.assign(inspection,{unit_id:unit.id,warehouse_id:unit.warehouse_id||warehouses.value[0]?.id||'',occurred_at:localDateTimeInput(),result:'available',reason:''});showInspection.value=true}
async function submitInspection(){if(!inspection.unit_id||!inspection.warehouse_id||!inspection.reason.trim()){error.value='请填写质检仓库和处理原因';return}loading.value=true;try{await opsRequest(props.token,'/inspections',{method:'POST',body:jsonBody({...inspection,occurred_at:new Date(inspection.occurred_at).toISOString()})});showInspection.value=false;ElMessage.success(inspection.result==='available'?'质检通过，实物已恢复可用':'质检完成，实物已报废');await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}}
function beginBundleComponents(unit:Row){Object.assign(bundleComponents,{unit_id:unit.id,warehouse_id:unit.warehouse_id||'',occurred_at:localDateTimeInput(),reason:'补录套装组成',unit_ids:[]});showBundleComponents.value=true}
async function submitBundleComponents(){if(!bundleComponents.unit_id||!bundleComponents.warehouse_id||!bundleComponents.unit_ids.length||!bundleComponents.reason.trim()){error.value='请选择组成件并填写仓库和原因';return}loading.value=true;try{await opsRequest(props.token,'/bundle-components',{method:'POST',body:jsonBody({...bundleComponents,occurred_at:new Date(bundleComponents.occurred_at).toISOString()})});showBundleComponents.value=false;ElMessage.success('套装组成关系已保存');await load()}catch(e){error.value=apiError(e)}finally{loading.value=false}}
async function searchTrace(term=q.value){if(!term.trim()){error.value='输入序列号、物料编码或销售单号后再查询';return}q.value=term;loading.value=true;error.value='';try{const result=await opsRequest<{units:Row[]}>(props.token,`/trace?q=${encodeURIComponent(term.trim())}`);trace.value=result.units;tab.value='trace'}catch(e){error.value=apiError(e)}finally{loading.value=false}}
const traceHistory=computed(()=>trace.value.flatMap(unit=>(unit.history||[]).map((event:Row)=>({...event,trace_unit:unit}))))
</script>

<template>
  <section>
    <header class="ops-toolbar"><div><div class="eyebrow">INVENTORY / TRACEABILITY</div><h1>库存与追溯</h1><p class="section-lead">按物料查看数量，登记入库、出库和套装操作，追踪单件实物流转。</p></div><div class="ops-actions"><el-input v-model="q" class="ops-search" clearable placeholder="搜索型号、物料、单据或序列号" @keyup.enter="searchTrace"/><el-button @click="searchTrace">序列号追溯</el-button><el-button v-if="writable" type="primary" @click="openReceipt()">办理入库</el-button><el-button v-if="writable" @click="openIssue">办理出库</el-button></div></header>
    <p v-if="error" class="ops-error">{{ error }}</p>
    <div class="ops-tabs"><button :class="{active:tab==='stock'}" @click="tab='stock'">库存总览</button><button :class="{active:tab==='units'}" @click="tab='units'">单件与批次</button><button :class="{active:tab==='movements'}" @click="tab='movements'">出入库记录</button><button :class="{active:tab==='trace'}" @click="tab='trace'">追溯时间线</button><span style="flex:1"/><el-button v-if="writable" @click="openAssembly">组装套装</el-button><el-button v-if="writable" @click="openDisassembly">拆解套装</el-button></div>
    <div v-if="tab==='stock'" class="panel ops-panel"><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>商品型号</th><th>物料编码</th><th>在库</th><th>可用</th><th>已预留</th><th>待检</th><th>借出未还</th><th>操作</th></tr></thead><tbody><tr v-for="row in stocks" :key="row.product_id"><td class="ops-row-title" :title="`${row.sku} · ${row.name}`">{{ row.sku }} · {{ row.name }}</td><td>{{ row.material_code||'—' }}</td><td>{{ row.in_stock }}</td><td>{{ row.available }}</td><td>{{ row.reserved }}</td><td>{{ row.pending }}</td><td>{{ row.borrowed }}</td><td><div class="ops-row-actions"><el-button v-if="writable" link @click="openReceipt(row.product_id)">入库</el-button><el-button link @click="tab='units';q=row.sku">单件</el-button></div></td></tr></tbody></table><div v-if="!stocks.length&&!loading" class="ops-empty">暂无库存数据</div></div><div class="ops-pagination"><span>共 {{ total }} 条</span><el-select v-model="size" style="width:95px"><el-option :value="10" label="10 条/页"/><el-option :value="20" label="20 条/页"/><el-option :value="50" label="50 条/页"/></el-select><el-button :disabled="page<=1" @click="page--">上一页</el-button><span>第 {{ page }} 页</span><el-button :disabled="page*size>=total" @click="page++">下一页</el-button></div></div>
    <div v-else-if="tab==='units'" class="panel ops-panel"><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>序列号 / 批次</th><th>商品</th><th>状态</th><th>仓库</th><th>套装归属</th><th>操作</th></tr></thead><tbody><tr v-for="unit in units" :key="unit.id"><td class="ops-row-title" :title="unit.serial_number||unit.batch_number">{{ unit.serial_number||unit.batch_number||'—' }}</td><td :title="`${unit.sku} · ${unit.name}`">{{ unit.sku }} · {{ unit.name }}</td><td><span class="ops-chip">{{ unit.traceability_pending?'组成待补':(status[unit.status]||unit.status) }}</span></td><td>{{ unit.warehouse_name||'—' }}</td><td>{{ unit.parent_id?'已装入套装':'—' }}</td><td><div class="ops-row-actions"><el-button link @click="q=unit.serial_number||unit.batch_number;void searchTrace()">追溯</el-button><el-button v-if="writable&&unit.status==='pending'" link type="primary" @click="beginInspection(unit)">质检</el-button><el-button v-if="writable&&unit.traceability_pending" link type="primary" @click="beginBundleComponents(unit)">补录组成</el-button></div></td></tr></tbody></table><div v-if="!units.length&&!loading" class="ops-empty">没有匹配的库存单件</div></div><div class="ops-pagination"><span>共 {{ total }} 条</span><el-select v-model="size" style="width:95px"><el-option :value="10" label="10 条/页"/><el-option :value="20" label="20 条/页"/><el-option :value="50" label="50 条/页"/></el-select><el-button :disabled="page<=1" @click="page--">上一页</el-button><span>第 {{ page }} 页</span><el-button :disabled="page*size>=total" @click="page++">下一页</el-button></div></div>
    <div v-else-if="tab==='movements'" class="panel ops-panel"><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>单据编号</th><th>类型</th><th>原因 / 接收方</th><th>发生时间</th><th>预计归还</th><th>销售订单</th><th>物流</th><th>费用</th><th>详情</th></tr></thead><tbody><tr v-for="row in movements" :key="row.id"><td class="ops-row-title">{{ row.number }}</td><td><span class="ops-chip">{{ types[row.type]||row.type }}</span></td><td :title="`${row.reason||''} ${row.recipient||''}`">{{ row.reason||row.recipient||'—' }}</td><td>{{ dateTime(row.occurred_at) }}</td><td>{{ dateTime(row.expected_return_at) }}</td><td>{{ row.sales_order_id||'—' }}</td><td :title="`${row.carrier||''} ${row.tracking_number||''}`">{{ row.carrier||'' }} {{ row.tracking_number||'' }}</td><td>{{ money(row.shipping_cost) }}</td><td><el-button link @click="movementDetail=row">查看明细</el-button></td></tr></tbody></table><div v-if="!movements.length&&!loading" class="ops-empty">暂无出入库单据</div></div><div class="ops-pagination"><span>共 {{ total }} 条</span><el-select v-model="size" style="width:95px"><el-option :value="10" label="10 条/页"/><el-option :value="20" label="20 条/页"/><el-option :value="50" label="50 条/页"/></el-select><el-button :disabled="page<=1" @click="page--">上一页</el-button><span>第 {{ page }} 页</span><el-button :disabled="page*size>=total" @click="page++">下一页</el-button></div></div>
    <div v-else class="panel ops-panel"><div class="panel-heading"><div><div class="eyebrow">SERIAL TRACE</div><h3>单件流转记录</h3></div><span class="ops-muted">{{ trace.length }} 件匹配的实物</span></div><div v-if="!trace.length" class="ops-empty">输入序列号、型号或销售单号查询完整流转记录</div><div v-for="unit in trace" :key="unit.id" style="padding:12px 0;border-top:1px solid var(--line)"><div class="ops-detail"><div><label>序列号 / 批次</label><strong>{{ unit.serial_number||unit.batch_number||'—' }}</strong></div><div><label>型号 / 物料编码</label><strong>{{ unit.sku }} · {{ unit.name }} · {{ unit.material_code||'—' }}</strong></div><div><label>当前状态</label><strong>{{ unit.traceability_pending?'组成待补':(status[unit.status]||unit.status) }} · {{ unit.warehouse_name||'无在库仓库' }}</strong></div><div><label>所属套装</label><strong>{{ unit.parent_id||'—' }}</strong></div></div><div class="ops-timeline"><article v-for="(event,index) in unit.history||[]" :key="`${event.number}-${index}`"><strong>{{ types[event.type]||event.type }} · {{ event.number }}</strong><span>{{ dateTime(event.occurred_at) }}{{ event.recipient?` · 去向：${event.recipient}`:'' }}{{ event.reason?` · 原因：${event.reason}`:'' }}</span><span v-if="event.carrier||event.tracking_number">{{ event.carrier }} · {{ event.tracking_number }}</span><span v-if="event.notes">{{ event.notes }}</span></article></div><div v-if="unit.components?.length" class="ops-muted">套装组成：{{ unit.components.map((c:Row)=>`${c.sku} ${c.serial_number||c.batch_number}`).join('；') }}</div></div></div>

    <el-dialog class="ops-dialog" v-model="showReceipt" title="办理入库" width="880px" destroy-on-close><div class="ops-form-grid"><el-form-item label="入库类型"><el-select v-model="receipt.type" style="width:100%"><el-option label="采购或生产入库" value="purchase"/><el-option label="期初库存" value="initial"/><el-option label="销售退货" value="return"/><el-option label="借样归还" value="borrow_return"/></el-select></el-form-item><el-form-item label="仓库"><el-select v-model="receipt.warehouse_id" placeholder="选择仓库" style="width:100%"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="发生时间"><el-date-picker v-model="receipt.occurred_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="来源方"><el-input v-model="receipt.recipient" placeholder="供应商、退货客户或归还人"/></el-form-item><el-form-item label="备注" class="span-two"><el-input v-model="receipt.notes" type="textarea" :rows="2"/></el-form-item></div><h3>入库商品</h3><p class="ops-muted">每件实物输入一行厂家序列号；数量由行数确定，保留大小写和前导零。</p><article v-for="(item,index) in receipt.items" :key="index" style="padding:12px 0;border-top:1px solid var(--line)"><div class="ops-inline"><ProductPicker v-model="item.product_id" :token="token" @select="(product)=>{item.product_label=product?`${product.sku} · ${product.name}`:'';item.product_kind=product?.kind||'';item.traceability_pending=product?.kind==='bundle'}"/><el-input v-model="item.batch_number" placeholder="生产批号"/><el-button link type="danger" @click="removeReceiptItem(Number(index))">移除</el-button></div><p v-if="item.product_kind==='bundle'" class="ops-muted">套装实物入库后会标记为“组成待补”，可在单件列表中登记实际组成。</p><el-input v-model="item.serial_text" type="textarea" :rows="3" placeholder="每行一个厂家序列号" style="margin-top:8px"/></article><el-button @click="addReceiptItem()">＋ 添加商品</el-button><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showReceipt=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitReceipt">确认入库</el-button></template></el-dialog>
    <el-dialog class="ops-dialog" v-model="showIssue" title="办理出库" width="920px" destroy-on-close><div class="ops-form-grid"><el-form-item label="出库类型"><el-select v-model="issue.type" style="width:100%"><el-option label="销售发货" value="sale"/><el-option label="寄样赠送" value="sample"/><el-option label="借样" value="borrow"/><el-option label="内部领用" value="internal"/><el-option label="报废" value="scrap"/></el-select></el-form-item><el-form-item label="仓库"><el-select v-model="issue.warehouse_id" style="width:100%"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item v-if="issue.type==='sale'" label="关联销售订单" class="span-two"><div class="ops-order-select"><el-input v-model="orderQuery" clearable placeholder="搜索销售单号、客户或外部单号"/><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>选择</th><th>销售单号</th><th>客户 / 店铺</th><th>状态</th><th>实付</th></tr></thead><tbody><tr v-for="order in orderRows" :key="order.id" :class="{'selected-row':issue.sales_order_id===order.id}" @click="selectIssueOrder(order)"><td><el-radio :model-value="issue.sales_order_id" :label="order.id">选择</el-radio></td><td>{{ order.number }}</td><td>{{ order.customer_name }} · {{ order.store_name||order.channel }}</td><td>{{ order.status==='open'?'待发货':order.status==='partial'?'部分发货':order.status }}</td><td>{{ money(order.paid_amount) }}</td></tr></tbody></table></div><div class="ops-pagination"><span>共 {{ orderTotal }} 条订单</span><el-button :disabled="orderPage<=1" @click="orderPage--">上一页</el-button><span>第 {{ orderPage }} 页</span><el-button :disabled="orderPage*10>=orderTotal" @click="orderPage++">下一页</el-button></div><span v-if="selectedOrder" class="ops-chip">已选择 {{ selectedOrder.number }}</span></div></el-form-item><el-form-item label="发生时间"><el-date-picker v-model="issue.occurred_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="接收方"><el-input v-model="issue.recipient" placeholder="客户、借用人或领用部门"/></el-form-item><el-form-item label="用途或原因"><el-input v-model="issue.reason"/></el-form-item><el-form-item v-if="issue.type==='borrow'" label="预计归还"><el-date-picker v-model="issue.expected_return_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="物流公司"><el-input v-model="issue.carrier"/></el-form-item><el-form-item label="运单号"><el-input v-model="issue.tracking_number"/></el-form-item><el-form-item label="物流费用"><el-input v-model="issue.shipping_cost"/></el-form-item><el-form-item label="备注"><el-input v-model="issue.notes"/></el-form-item></div><h3>选择可出库实物</h3><UnitPicker v-model="issue.unit_ids" :token="token" :status="issue.type==='sale'&&issue.sales_order_id?'dispatchable':'available'" :dispatch-order-id="issue.type==='sale'?issue.sales_order_id:''" :warehouse-id="issue.warehouse_id"/><p v-if="issue.type==='sale'" class="ops-muted">可选库存包含可用实物和已为此销售订单预留的实物。</p><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showIssue=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitIssue">确认出库</el-button></template></el-dialog>
    <el-dialog class="ops-dialog" v-model="showAssembly" title="组装套装" width="800px" destroy-on-close><div class="ops-form-grid"><el-form-item label="套装商品"><ProductPicker v-model="assembly.product_id" :token="token" @select="(p)=>{assembly.product_label=p?`${p.sku} · ${p.name}`:'';assembly.bom_configured=p?.bom_configured??null}"/></el-form-item><el-form-item label="内部套装追溯码"><el-input v-model="assembly.serial_number"/></el-form-item><el-form-item label="生产批号"><el-input v-model="assembly.batch_number"/></el-form-item><el-form-item label="仓库"><el-select v-model="assembly.warehouse_id" style="width:100%"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="组装时间"><el-date-picker v-model="assembly.occurred_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="备注"><el-input v-model="assembly.notes"/></el-form-item></div><p v-if="assembly.bom_configured===false" class="ops-error">该套装未配置组成模板，请按实际商品组成选择并核对。</p><h3>选择组成件</h3><UnitPicker v-model="assembly.unit_ids" :token="token" status="available" :warehouse-id="assembly.warehouse_id"/><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showAssembly=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitAssembly">确认组装</el-button></template></el-dialog>
    <el-dialog class="ops-dialog" v-model="showDisassembly" title="拆解套装" width="760px" destroy-on-close><el-form-item label="拆套仓库"><el-select v-model="disassembly.warehouse_id" style="width:100%"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="拆套时间"><el-date-picker v-model="disassembly.occurred_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="拆套原因"><el-input v-model="disassembly.reason"/></el-form-item><h3>选择已组套实物</h3><UnitPicker v-model="disassembly.unit_ids" :token="token" status="assembled" :warehouse-id="disassembly.warehouse_id" :multiple="false" @change="updateDisassemblyUnits"/><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showDisassembly=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitDisassembly">确认拆套</el-button></template></el-dialog>
    <el-dialog class="ops-dialog" v-model="showInspection" title="实物质检" width="520px"><div class="ops-muted">待检实物通过后恢复为可用库存；不合格时记为报废。</div><el-form-item label="处理结果"><el-select v-model="inspection.result" style="width:100%"><el-option label="质检通过，恢复可用" value="available"/><el-option label="质检不合格，报废" value="scrapped"/></el-select></el-form-item><el-form-item label="质检仓库"><el-select v-model="inspection.warehouse_id" style="width:100%"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="处理时间"><el-date-picker v-model="inspection.occurred_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="处理原因"><el-input v-model="inspection.reason" type="textarea" :rows="2"/></el-form-item><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showInspection=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitInspection">确认质检</el-button></template></el-dialog>
    <el-dialog class="ops-dialog" v-model="showBundleComponents" title="补录套装组成" width="800px" destroy-on-close><div class="ops-muted">该套装已入库；这里只登记实物组成关系，不重复增加库存。</div><div class="ops-form-grid"><el-form-item label="套装所在仓库"><el-select v-model="bundleComponents.warehouse_id" style="width:100%"><el-option v-for="w in warehouses" :key="w.id" :label="w.name" :value="w.id"/></el-select></el-form-item><el-form-item label="记录时间"><el-date-picker v-model="bundleComponents.occurred_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="原因" class="span-two"><el-input v-model="bundleComponents.reason"/></el-form-item></div><h3>选择组成件</h3><UnitPicker v-model="bundleComponents.unit_ids" :token="token" status="available" :warehouse-id="bundleComponents.warehouse_id"/><p v-if="error" class="ops-error">{{ error }}</p><template #footer><el-button @click="showBundleComponents=false">取消</el-button><el-button type="primary" :loading="loading" @click="submitBundleComponents">保存组成关系</el-button></template></el-dialog>
    <el-dialog class="ops-dialog" v-model="movementDialogOpen" title="出入库单据详情" width="680px"><div v-if="movementDetail"><div class="ops-detail"><div><label>单据编号</label><strong>{{ movementDetail.number }}</strong></div><div><label>业务类型</label><strong>{{ types[movementDetail.type]||movementDetail.type }}</strong></div><div><label>发生时间</label><strong>{{ dateTime(movementDetail.occurred_at) }}</strong></div><div><label>接收方</label><strong>{{ movementDetail.recipient||'—' }}</strong></div><div><label>物流</label><strong>{{ movementDetail.carrier||'—' }} · {{ movementDetail.tracking_number||'—' }}</strong></div><div><label>物流费用</label><strong>{{ money(movementDetail.shipping_cost) }}</strong></div><div class="span-two"><label>备注</label><strong>{{ movementDetail.notes||movementDetail.reason||'—' }}</strong></div></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>商品</th><th>批次</th><th>序列号</th></tr></thead><tbody><tr v-for="(item,index) in movementDetail.items||[]" :key="index"><td>{{ item.sku }} · {{ item.name }}</td><td>{{ item.batch_number||'—' }}</td><td :title="item.serial_number">{{ item.serial_number||'—' }}</td></tr><tr v-if="!movementDetail.items?.length"><td colspan="3">该单据没有返回明细</td></tr></tbody></table></div></div></el-dialog>
  </section>
</template>

<style scoped>.ops-order-select{width:100%}.ops-order-select .ops-table-wrap{max-height:250px;overflow:auto}.ops-order-select .ops-table{min-width:650px}.ops-order-select tr{cursor:pointer}.ops-order-select .selected-row td{background:#f6f1e8}</style>
